package framework

import (
	"bytes"
	"context"
	"testing"
	"time"
)

func TestConfigurationAndSessionReadsDoNotWaitForUncommittedWriter(t *testing.T) {
	s := storeOpen(t, RoleSystem)
	original := storeDoc(t, storeFixtureSystem())
	if err := s.SaveConfig(original); err != nil {
		t.Fatal(err)
	}
	committed, err := s.Config()
	if err != nil {
		t.Fatal(err)
	}
	// The valid fixture verifier is generated by the existing account tests.
	hash := []byte("$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy")
	if err := s.SetAccount("admin", hash); err != nil {
		t.Fatal(err)
	}
	if err := s.WriteCache("connection", []byte(`{"state":"Connected"}`)); err != nil {
		t.Fatal(err)
	}
	expiry := time.Now().Add(time.Hour)
	if err := s.authPut("session", "reader-test", map[string]string{"value": "committed"}, expiry); err != nil {
		t.Fatal(err)
	}
	tx, err := s.db.Begin()
	if err != nil {
		t.Fatal(err)
	}
	defer tx.Rollback()
	if _, err = tx.Exec(`UPDATE framework_documents SET document='{"pending":true}' WHERE name='config'`); err != nil {
		t.Fatal(err)
	}
	done := make(chan error, 1)
	go func() {
		raw, err := s.Config()
		if err == nil && !bytes.Equal(raw, committed) {
			t.Error("read exposed uncommitted configuration")
		}
		if err == nil {
			_, _, err = s.Account()
		}
		if err == nil {
			_, _, err = s.ReadCache("connection")
		}
		var record map[string]string
		if err == nil {
			err = s.authRead("session", "reader-test", &record)
		}
		if err == nil && record["value"] != "committed" {
			t.Error("committed session unavailable")
		}
		done <- err
	}()
	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(300 * time.Millisecond):
		tx.Rollback()
		<-done
		t.Fatal("read queued behind configuration writer")
	}
	if err = tx.Rollback(); err != nil {
		t.Fatal(err)
	}
	if _, err = s.readDB.ExecContext(context.Background(), `DELETE FROM framework_documents`); err == nil {
		t.Fatal("configuration reader permits writes")
	}
}
